   221→    let sum = 0, cnt = 0;
   222→    for (let j = Math.max(0, i - 5); j <= Math.min(bpmSeq.length - 1, i + 5); j++) { sum += bpmSeq[j]; cnt++; }
   223→    detr.push(bpmSeq[i] - sum / cnt);
