    91→function classifyRhythm(hrMad, successiveMad, jumpRatio, quality, baseline, w) {
    92→  if (hrMad == null || successiveMad == null) return dimResult(0, 50, 'unknown', getText('dim_label_unknown'), 5, 0.2, [], ['hrMad']);
    93→  const instability = clamp(hrMad / 6 * 0.45 + successiveMad / 5 * 0.35 + jumpRatio / 0.12 * 0.20, 0, 1);
    94→  let category, label;
    95→  if (instability < 0.22) { category = 'stable'; label = getText('dim_label_rhythm_stable'); }
    96→  else if (instability < 0.40) { category = 'mostly_stable'; label = getText('dim_label_rhythm_mostly_stable'); }
    97→  else if (instability < 0.60) { category = 'moderate'; label = getText('dim_label_rhythm_moderate'); }
    98→  else { category = 'variable'; label = getText('dim_label_rhythm_variable'); }
    99→  // 双轨融合：波动度相对个人常态校准（hrMad 为基线特征），标签仍按绝对不稳定度分档。
   100→  const fused = fuseStateIndex(instability * 100, hrMad, baseline && baseline.rhythm, w);
   101→  return dimResult(instability, fused, category, label, clamp(9 - fused / 100 * 7, 2, 9), quality, ['hr_mad', 'successive_change', 'jump_ratio'], []);
   102→}
   103→
   104→function classifyStrength(dayRange, sleepScore, stress, firstLastDelta, quality, ltIndex, wLT) {
   105→  const missing = [];
   106→  if (!(dayRange > 0)) missing.push('dayRange');
   107→  if (!(sleepScore > 0)) missing.push('sleepScore');
   108→  if (!(stress > 0)) missing.push('stress');
   109→  const vitality = (dayRange > 0 ? clamp(dayRange / 45, 0, 1) : 0.5) * 0.30 +
   110→    (sleepScore > 0 ? clamp(sleepScore / 10, 0, 1) : 0.5) * 0.30 +
   111→    (stress > 0 ? 1 - clamp(stress / 100, 0, 1) : 0.5) * 0.20 +
   112→    clamp((4 - firstLastDelta) / 10, 0, 1) * 0.20;
   113→  let category, label;
   114→  if (vitality < 0.30) { category = 'xu'; label = getText('dim_label_strength_xu'); }
   115→  else if (vitality < 0.44) { category = 'pian_xu'; label = getText('dim_label_strength_pian_xu'); }
   116→  else if (vitality < 0.66) { category = 'ping'; label = getText('dim_label_ping'); }
   117→  else if (vitality < 0.80) { category = 'pian_shi'; label = getText('dim_label_strength_pian_shi'); }
   118→  else { category = 'shi'; label = getText('dim_label_strength_shi'); }
   119→  // 长期变异性(SDANN)相对校准：只挪数值/雷达，标签保绝对；wLT=0（无长时程基线）与旧版逐字节一致。
   120→  let stateIdx = vitality * 100;
   121→  if (wLT && ltIndex != null) stateIdx = clamp(stateIdx * (1 - wLT) + ltIndex * wLT, 0, 100);
   122→  return dimResult(vitality, stateIdx, category, label, centeredScore(stateIdx, 55, 45), quality, ['day_range', 'sleep', 'stress'], missing);
   123→}
   124→
   125→function classifyWidth(hrRange90, hrMad, patternEntropy, quality) {
   126→  if (hrRange90 == null || hrMad == null) return dimResult(0, 50, 'unknown', getText('dim_label_unknown'), 5, 0.2, [], ['hrRange90']);
   127→  const width = clamp(hrRange90 / 14, 0, 1) * 0.55 + clamp(hrMad / 5, 0, 1) * 0.25 +
   128→    (patternEntropy != null ? clamp(patternEntropy / 3, 0, 1) : 0.5) * 0.20;
   129→  let category, label;
   130→  if (width < 0.24) { category = 'xi'; label = getText('dim_label_width_xi'); }
   131→  else if (width < 0.40) { category = 'pian_xi'; label = getText('dim_label_width_pian_xi'); }
   132→  else if (width < 0.66) { category = 'ping'; label = getText('dim_label_ping'); }
   133→  else if (width < 0.82) { category = 'pian_hong'; label = getText('dim_label_width_pian_hong'); }
   134→  else { category = 'hong'; label = getText('dim_label_width_hong'); }
   135→  return dimResult(width, width * 100, category, label, centeredScore(width * 100, 55, 50), quality, ['hr_range', 'hr_mad', 'pattern_entropy'], []);
   136→}
   137→
   138→function classifyTension(stress, hr, restingHr, successiveMad, trendSlope, sleepScore, quality, baseline, w) {
   139→  const missing = stress > 0 ? [] : ['stress'];
   140→  const restBase = restingHr > 0 ? restingHr : hr;
   141→  const tension = (stress > 0 ? clamp(stress / 100, 0, 1) : 0.5) * 0.45 +
   142→    clamp((hr - restBase + 5) / 25, 0, 1) * 0.20 + clamp(successiveMad / 5, 0, 1) * 0.15 +
   143→    clamp((trendSlope + 2) / 8, 0, 1) * 0.10 + (sleepScore > 0 ? 1 - sleepScore / 10 : 0.5) * 0.10;
   144→  let category, label;
   145→  if (tension < 0.25) { category = 'ruan'; label = getText('dim_label_tension_ruan'); }
   146→  else if (tension < 0.42) { category = 'ru'; label = getText('dim_label_tension_ru'); }
   147→  else if (tension < 0.60) { category = 'ping'; label = getText('dim_label_ping'); }
   148→  else if (tension < 0.76) { category = 'pian_xian'; label = getText('dim_label_tension_pian_xian'); }
   149→  else { category = 'xian'; label = getText('dim_label_tension_xian'); }
   150→  // 双轨融合：张力相对个人常态(stress 基线)校准，标签保绝对；w=0（无基线）与旧版逐字节一致。
   151→  const stateIdx = fuseStateIndex(tension * 100, stress > 0 ? stress : null, baseline && baseline.stress, w);
   152→  return dimResult(tension, stateIdx, category, label, centeredScore(stateIdx, 48, 52), quality, ['stress', 'hr_elevation', 'trend'], missing);
   153→}
