   155→// ============================================================================
   156→// 五脏 & 体质 (msgid)
   157→// ============================================================================
   158→// 由内部 key（organKey/statusKey）映射到五脏描述 msgid，与语言无关
   159→function organDescKey(organKey, statusKey) {
   160→  const map = {
   161→    heart:  { he: 'organ_desc_heart_he',  ping: 'organ_desc_heart_ping',  xu: 'organ_desc_heart_xu',  kui: 'organ_desc_heart_kui' },
   162→    liver:  { he: 'organ_desc_liver_he',  ping: 'organ_desc_liver_ping',  xu: 'organ_desc_liver_xu',  kui: 'organ_desc_liver_kui' },
   163→    spleen: { he: 'organ_desc_spleen_he', ping: 'organ_desc_spleen_ping', xu: 'organ_desc_spleen_xu', kui: 'organ_desc_spleen_kui' },
   164→    lung:   { he: 'organ_desc_lung_he',   ping: 'organ_desc_lung_ping',   xu: 'organ_desc_lung_xu',   kui: 'organ_desc_lung_kui' },
   165→    kidney: { he: 'organ_desc_kidney_he', ping: 'organ_desc_kidney_ping', xu: 'organ_desc_kidney_xu', kui: 'organ_desc_kidney_kui' },
   166→  };
   167→  return map[organKey]?.[statusKey] || '';
   168→}
   169→
   170→// ============================================================================
   171→// 主脉象匹配 v2：使用绝对匹配度，不再把第一名强制归一化为 1。
   172→// 1Hz 心率能够稳定支持的特征优先，浮/沉/结/代保留在知识库中。
   173→// ============================================================================
   174→function matchPulseType(dimensions, metrics) {
   175→  const hr = metrics.medianHr || metrics.mean_hr || metrics.restingHr || 0;
   176→  const stress = metrics.stress || 0;
   177→  const range = metrics.hrRange90 || 0;
   178→  const hrMad = metrics.hrMad || 0;
   179→  const successiveMad = metrics.successiveMad || 0;
   180→  const jumpRatio = metrics.jumpRatio || 0;
   181→  const quality = metrics.qualityScore == null ? 0.7 : metrics.qualityScore / 100;
   182→  const smooth = 1 - clamp(jumpRatio / 0.15, 0, 1);
   183→  const strengthIndex = (dimensions.strength.stateIndex == null ? 50 : dimensions.strength.stateIndex) / 100;
   184→  const widthIndex = (dimensions.width.stateIndex == null ? 50 : dimensions.width.stateIndex) / 100;
   185→  const tensionIndex = (dimensions.tension.stateIndex == null ? 50 : dimensions.tension.stateIndex) / 100;
   186→  const rhythmBalance = dimensions.rhythm.score / 9;
   187→  const scores = {};
   188→
   189→  scores.chi = clamp((58 - hr) / 18, 0, 1) * 0.80 + (hr < 58 ? 0.12 : 0.02);
   190→  scores.shuo = clamp((hr - 76) / 24, 0, 1) * 0.80 + (hr > 76 ? 0.12 : 0.02);
   191→  scores.huan = clamp(1 - Math.abs(hr - 68) / 26, 0, 1) * 0.38 + rhythmBalance * 0.34 +
   192→    (1 - Math.abs(tensionIndex - 0.48)) * 0.18 + smooth * 0.10;
   193→  scores.xian = tensionIndex * 0.55 + clamp((stress - 35) / 65, 0, 1) * 0.25 +
   194→    clamp((hr - 65) / 30, 0, 1) * 0.20;
   195→  scores.hua = smooth * 0.35 + clamp(range / 12, 0, 1) * 0.25 +
   196→    clamp((metrics.patternEntropy || 0) / 3, 0, 1) * 0.20 + rhythmBalance * 0.20;
   197→  scores.se = (1 - smooth) * 0.42 + clamp(successiveMad / 5, 0, 1) * 0.28 +
   198→    tensionIndex * 0.20 + (1 - quality) * 0.10;
   199→  scores.xu = (1 - strengthIndex) * 0.62 + (1 - dimensions.rate.score / 9) * 0.18 +
   200→    (1 - quality) * 0.20;
   201→  scores.shi = strengthIndex * 0.62 + dimensions.rate.score / 9 * 0.18 + quality * 0.20;
   202→  scores.xi = (1 - widthIndex) * 0.62 + (1 - strengthIndex) * 0.23 + smooth * 0.15;
   203→
   204→  // 洪脉保留为较常见的充盛型倾向，但不再由全天极值单独触发。
   205→  scores.hong = clamp(range / 14, 0, 1) * 0.35 + strengthIndex * 0.30 + smooth * 0.20 +
   206→    clamp((metrics.dayRange || 0) / 45, 0, 1) * 0.15;
   207→  if (range < 5 || strengthIndex < 0.45) scores.hong *= 0.72;
   208→
   209→  // 低质量数据不产生极端文化映射，优先回落到缓脉或混合特征。
   210→  if (quality < 0.65) {
   211→    ['hua', 'se', 'xu', 'shi', 'xi', 'hong'].forEach(k => { scores[k] *= 0.72; });
   212→    scores.huan *= 0.90;
   213→  }
   214→
   215→  // 排序保留计算精度，避免一位小数把不同匹配度变成同分。
   216→  Object.keys(scores).forEach(k => { scores[k] = clamp(scores[k], 0, 1); });
   217→  const ranked = Object.entries(scores).sort((a, b) => b[1] - a[1]);
   218→  const bestType = ranked[0] ? ranked[0][0] : 'huan';
   219→  const bestScore = ranked[0] ? ranked[0][1] : 0;
   220→  const secondType = ranked[1] ? ranked[1][0] : null;
   221→  const secondScore = ranked[1] ? ranked[1][1] : 0;
   222→  const margin = Math.max(0, bestScore - secondScore);
   223→  const confidence = clamp(bestScore * 0.55 + clamp(margin / 0.25, 0, 1) * 0.25 + quality * 0.20, 0, 1);
   224→  const certainty = confidence >= 0.75 ? 'primary' : confidence >= 0.60 ? 'close' : confidence >= 0.45 ? 'mixed' : 'unclear';
   225→
   226→  const PULSE_TYPES = resolvePulseTypes();
   227→  const info = PULSE_TYPES[bestType];
   228→  const secondInfo = secondType ? PULSE_TYPES[secondType] : null;
   229→  return {
   230→    type: bestType, name: info.name, description: info.desc, nature: info.nature,
   231→    confidence: round1(confidence), certainty,
   232→    secondary: secondInfo ? { type: secondType, name: secondInfo.name, score: secondScore } : null,
   233→    margin: round1(margin), allScores: scores
   234→  };
   235→}
   236→
   237→// ============================================================================
   238→// 体质判定（中医九种体质）
   239→// 每种体质一个启发式打分，综合 HRV 指标与六维分类结果；归一化后取最高者为体质。
   240→// 权重反映中医理论（如阳虚 → 心率慢 + 脉势弱；气郁 → 压力高 + 紧张度弦）。
   241→// ============================================================================
   242→function assessConstitution(dimensions, mainPulse, metrics, baseline, w) {
   243→  const stress = metrics.stress || 0;
   244→  const hr = metrics.medianHr || metrics.restingHr || 0;
   245→  const scores = {};
   246→  const strengthLow = clamp((45 - dimensions.strength.stateIndex) / 45, 0, 1);
   247→  const tensionHigh = clamp((dimensions.tension.stateIndex - 48) / 52, 0, 1);
   248→  const widthHigh = clamp((dimensions.width.stateIndex - 55) / 45, 0, 1);
   249→  const rhythmVariable = clamp(dimensions.rhythm.stateIndex / 100, 0, 1);
   250→  const balanceAvg = (dimensions.rate.score + dimensions.rhythm.score + dimensions.strength.score + dimensions.width.score + dimensions.tension.score + dimensions.rsa.score) / 54;
   251→
   252→  // 相对个人常态的心率 z：无基线/冷启动时 null → 下面三个绝对阈值项与旧版完全一致。
   253→  const zHr = (w && baseline && baseline.hr && finite(baseline.hr.med) && finite(baseline.hr.mad) && baseline.hr.mad > 0)
   254→    ? (hr - baseline.hr.med) / baseline.hr.mad : null;
   255→  // 绝对阈值虽触发，但若“只是他自己的常态”，按基线成熟度 w 向 floor 回拉、弱化病理性判定（保留绝对锚）。
   256→  // support∈[0,1]：本次相对常态是否朝同方向偏离（偏慢/偏快）；不偏离则回拉 w 成。
   257→  function softenAbs(term, full, floor, support) {
   258→    if (zHr == null || term <= floor) return term;
   259→    return full - (full - floor) * clamp(w * clamp(1 - support, 0, 1), 0, 1);
   260→  }
   261→  const slowSupport = zHr == null ? 0 : clamp(-zHr, 0, 1);
   262→  const fastSupport = zHr == null ? 0 : clamp(zHr, 0, 1);
   263→
   264→  scores.balanced = clamp(balanceAvg, 0, 1) * 0.85;
   265→  scores.qi_deficiency = strengthLow * 0.60 + (1 - dimensions.rsa.score / 9) * 0.40;
   266→  scores.yang_deficiency = softenAbs(hr > 0 && hr < 58 ? 0.65 : 0.18, 0.65, 0.18, slowSupport) * 0.45 + strengthLow * 0.55;
   267→  scores.yin_deficiency = softenAbs(hr > 78 ? 0.65 : 0.18, 0.65, 0.18, fastSupport) * 0.45 + clamp(stress / 100, 0, 1) * 0.55;
   268→  scores.qi_stagnation = clamp(stress / 85, 0, 1) * 0.55 + tensionHigh * 0.45;
   269→  scores.blood_stasis = rhythmVariable * 0.35 + tensionHigh * 0.35 + (mainPulse.type === 'se' ? 0.30 : 0.08);
   270→  scores.phlegm_damp = strengthLow * 0.45 + widthHigh * 0.35 + (metrics.sleepScore > 0 && metrics.sleepScore < 6 ? 0.20 : 0.06);
   271→  scores.damp_heat = softenAbs(hr > 74 ? 0.45 : 0.15, 0.45, 0.15, fastSupport) * 0.35 + clamp(stress / 90, 0, 1) * 0.40 + clamp((dimensions.strength.stateIndex - 55) / 45, 0, 1) * 0.25;
   272→  scores.allergic = 0.12 + rhythmVariable * 0.18;
   273→
   274→  const ranked = Object.entries(scores).sort((a, b) => b[1] - a[1]);
   275→  const bestType = ranked[0] ? ranked[0][0] : 'balanced';
   276→  const bestScore = ranked[0] ? ranked[0][1] : 0;
   277→  const secondScore = ranked[1] ? ranked[1][1] : 0;
   278→  const CONSTITUTIONS = resolveConstitutions();
   279→  const cnst = CONSTITUTIONS[bestType];
   280→  return {
   281→    type: bestType, name: cnst.name, description: cnst.desc,
   282→    score: round1(clamp(bestScore, 0, 1)), margin: round1(Math.max(0, bestScore - secondScore)),
   283→    confidence: round1(clamp((metrics.qualityScore == null ? 72 : metrics.qualityScore) / 100 * 0.5 + Math.max(0, bestScore - secondScore) * 2 * 0.5, 0, 1)),
   284→    allScores: scores
   285→  };
   286→}
   287→
   288→// ============================================================================
   289→// 五脏关联
   290→// 每脏一个 0-10 综合分（六维得分 + 全天指标加权），再映射为状态：
   291→//   score >= 7 → 和（he）   >= 5 → 平（ping）   >= 3 → 虚（xu）   否则 → 亏（kui）
   292→// 元素同时携带内部 key（organKey/statusKey，语言无关）与本地化文本
   293→// （organ/status），供 organDescKey 查描述 msgid、generateRecommendations
   294→// 做器官比较，以及 UI 直接展示。
   295→// ============================================================================
   296→function analyzeOrgans(dimensions, mainPulse, metrics) {
   297→  const stress = metrics.stress || 0;
   298→  const sleepScore = metrics.sleepScore || 0;
   299→  const quality = clamp((metrics.qualityScore == null ? 72 : metrics.qualityScore) / 100, 0, 1);
   300→  const heartScore = dimensions.rhythm.score * 0.45 + dimensions.rate.score * 0.30 + (sleepScore || 6) * 0.15 + quality * 10 * 0.10;
   301→  const liverScore = dimensions.tension.score * 0.55 + (stress > 0 ? (100 - stress) / 10 : 6) * 0.30 + dimensions.rsa.score * 0.15;
   302→  const spleenScore = dimensions.width.score * 0.35 + dimensions.strength.score * 0.45 + (sleepScore || 6) * 0.20;
   303→  const lungScore = dimensions.strength.score * 0.40 + dimensions.rhythm.score * 0.40 + dimensions.rsa.score * 0.20;
   304→  const kidneyScore = dimensions.strength.score * 0.50 + dimensions.rsa.score * 0.30 + (sleepScore || 6) * 0.20;
   305→
   306→  const organs = [
   307→    { organ: getText('organ_name_heart'), organKey: 'heart', score: round1(clamp(heartScore, 0, 10)) },
   308→    { organ: getText('organ_name_liver'), organKey: 'liver', score: round1(clamp(liverScore, 0, 10)) },
   309→    { organ: getText('organ_name_spleen'), organKey: 'spleen', score: round1(clamp(spleenScore, 0, 10)) },
   310→    { organ: getText('organ_name_lung'), organKey: 'lung', score: round1(clamp(lungScore, 0, 10)) },
   311→    { organ: getText('organ_name_kidney'), organKey: 'kidney', score: round1(clamp(kidneyScore, 0, 10)) },
   312→  ];
   313→
   314→  organs.forEach(o => {
   315→    if (o.score >= 7) { o.statusKey = 'he'; o.status = getText('organ_status_he'); }
   316→    else if (o.score >= 5) { o.statusKey = 'ping'; o.status = getText('organ_status_ping'); }
   317→    else if (o.score >= 3) { o.statusKey = 'xu'; o.status = getText('organ_status_xu'); }
   318→    else { o.statusKey = 'kui'; o.status = getText('organ_status_kui'); }
   319→    o.desc = getText(organDescKey(o.organKey, o.statusKey));
   320→    o.confidence = round1(quality);
   321→  });
   322→  return organs;
   323→}
