   325→// ============================================================================
   326→// 养生建议
   327→// 根据体质类型、最虚弱脏器、六维细分级三维联动生成个性化建议。
   328→// ── 饮食：优先按体质类型匹配专属建议，其次按六维信号补充 ──
   329→// ── 作息：优先按最虚弱脏器匹配，其次按张力/恢复信号补充 ──
   330→// ── 运动：按力量维/宽度维/恢复维细分级匹配 ──
   331→// ── 情志：按体质类型 + 张力维联动匹配 ──
   332→// ============================================================================
   333→function generateRecommendations(dimensions, constitution, organAnalysis, metrics) {
   334→  const recs = [];
   335→  const separator = getText('rec_separator');
   336→  const isFast = dimensions.rate.category === 'pian_shuo' || dimensions.rate.category === 'shuo';
   337→  const isTense = dimensions.tension.category === 'pian_xian' || dimensions.tension.category === 'xian';
   338→  const isWeak = dimensions.strength.category === 'xu' || dimensions.strength.category === 'pian_xu';
   339→  const isFull = dimensions.width.category === 'pian_hong' || dimensions.width.category === 'hong';
   340→  const slowRecovery = dimensions.rsa.category === 'slow' || dimensions.rsa.category === 'settling';
   341→  const ct = constitution.type;
   342→
   343→  // ── 饮食：体质专属 → 六维补充 ──
   344→  const diet = [];
   345→  const dietByConstitution = {
   346→    qi_deficiency:   'rec_diet_qi_def',
   347→    yang_deficiency: 'rec_diet_yang_def',
   348→    yin_deficiency:  'rec_diet_yin_def',
   349→    qi_stagnation:   'rec_diet_qi_stag',
   350→    phlegm_damp:     'rec_diet_phlegm_damp',
   351→    damp_heat:       'rec_diet_damp_heat',
   352→    blood_stasis:    'rec_diet_blood_stasis',
   353→    allergic:        'rec_diet_allergic',
   354→  };
   355→  const dietKey = dietByConstitution[ct];
   356→  if (dietKey) {
   357→    diet.push(getText(dietKey));
   358→  } else {
   359→    diet.push(getText('rec_diet_default'));
   360→  }
   361→  // 六维补充：数脉/弦脉倾向者额外提醒饮食调养
   362→  if (isFast && isTense) diet.push(getText('rec_diet_calm'));
   363→  recs.push({ category: getText('rec_cat_diet'), advice: diet.join(separator), priority: isFast || isTense ? 1 : 3 });
   364→
   365→  // ── 作息：最虚弱脏器 → 张力/恢复补充 ──
   366→  const rest = [];
   367→  const sortedOrgans = organAnalysis.slice().sort((a, b) => a.score - b.score);
   368→  const worstOrgan = sortedOrgans[0];
   369→  if (worstOrgan && worstOrgan.organKey === 'liver' && worstOrgan.score < 5) {
   370→    rest.push(getText('rec_rest_liver'));
   371→  } else if (worstOrgan && worstOrgan.organKey === 'heart' && worstOrgan.score < 5) {
   372→    rest.push(getText('rec_rest_heart'));
   373→  } else if (isWeak || slowRecovery) {
   374→    rest.push(getText('rec_rest_recovery'));
   375→  } else if (isTense || isFast) {
   376→    rest.push(getText('rec_rest_calm'));
   377→  } else {
   378→    rest.push(getText('rec_rest_default'));
   379→  }
   380→  if (isTense || isFast) rest.push(getText('rec_rest_no_caffeine'));
   381→  recs.push({ category: getText('rec_cat_rest'), advice: rest.join(separator), priority: isWeak || slowRecovery ? 1 : 2 });
   382→
   383→  // ── 运动：力量维/宽度维/恢复维细分级 ──
   384→  const exercise = [];
   385→  if (isWeak || slowRecovery) {
   386→    exercise.push(getText('rec_exercise_gentle'));
   387→  } else if (isFull) {
   388→    exercise.push(getText('rec_exercise_cardio'));
   389→  } else if (isTense) {
   390→    exercise.push(getText('rec_exercise_relax'));
   391→  } else {
   392→    exercise.push(getText('rec_exercise_default'));
   393→  }
