   291→// ============================================================================
   292→// RSA 呼吸-心率耦合评估
   293→// ============================================================================
   294→function classifyRsa(eiRatio) {
   295→  if (eiRatio == null || eiRatio <= 0) return { value: 0, category: 'unknown', label: getText('dim_label_unknown'), score: 5 };
   296→  if (eiRatio < 1.03) return { value: eiRatio, category: 'rigid',      label: getText('dim_label_rsa_rigid'),      score: 2 };
   297→  if (eiRatio < 1.06) return { value: eiRatio, category: 'blunted',    label: getText('dim_label_rsa_blunted'),    score: 4 };
   298→  if (eiRatio < 1.10) return { value: eiRatio, category: 'normal',     label: getText('dim_label_rsa_normal'),     score: 6 };
   299→  if (eiRatio < 1.15) return { value: eiRatio, category: 'flexible',   label: getText('dim_label_rsa_flexible'),   score: 8 };
   300→  return { value: eiRatio, category: 'highly_flexible', label: getText('dim_label_rsa_highly_flexible'), score: 9 };
   301→}
