   303→// ============================================================================
   304→// 主入口
   305→// ============================================================================
   306→export function diagnosePulse(metrics) {
   307→  const { 
   308→    sdnn = 0, sdann = 0, restingHr = 0, avgHr = 0, mean_hr = 0, 
   309→    hrStability = 0, sdnnSegments = [], stress = 0, sleepScore = 0, 
   310→    hrReserve = 0, patternEntropy = 0, lfRms = 0, vlfRms = 0,
   311→    rsaEiRatio = 0
   312→  } = metrics;
   313→
   314→  // 使用新提取的非线性指标 (Pattern Entropy) 和 频域 (LF/VLF RMS) 修正节律和宽度
   315→  let adjustedSdnn = sdnn;
   316→  let adjustedStress = stress;
   317→
   318→  if (patternEntropy > 0) {
   319→    if (patternEntropy < 1.0) adjustedSdnn = Math.max(0, adjustedSdnn - 10);
   320→    else if (patternEntropy > 2.5) adjustedSdnn = Math.min(100, adjustedSdnn + 10);
   321→  }
   322→
   323→  if (lfRms > 0 && vlfRms > 0) {
   324→    const lfVlfRatio = lfRms / vlfRms;
   325→    if (lfVlfRatio > 2.0) adjustedStress = Math.min(100, adjustedStress + 15);
   326→    else if (lfVlfRatio < 0.5) adjustedStress = Math.max(0, adjustedStress - 15);
   327→  }
   328→
   329→  const dimensions = {
   330→    rate:     classifyRate(restingHr || avgHr || mean_hr),
   331→    rhythm:   classifyRhythm(adjustedSdnn),
   332→    strength: classifyStrength(sdann, hrReserve),
   333→    width:    classifyWidth(hrStability, adjustedStress),
   334→    tension:  classifyTension(adjustedStress, adjustedSdnn),
   335→    rsa:      classifyRsa(rsaEiRatio)
   336→  };
   337→
   338→  let segmentTrend = 'stable';
   339→  if (sdnnSegments.length >= 3) {
   340→    const first = sdnnSegments.slice(0, Math.ceil(sdnnSegments.length / 2));
   341→    const second = sdnnSegments.slice(Math.ceil(sdnnSegments.length / 2));
   342→    const avgFirst = first.reduce((a, b) => a + b, 0) / first.length;
   343→    const avgSecond = second.reduce((a, b) => a + b, 0) / second.length;
   344→    if (avgFirst > 0 && avgSecond / avgFirst > 1.1) segmentTrend = 'relaxing';
   345→    else if (avgFirst > 0 && avgSecond / avgFirst < 0.9) segmentTrend = 'tiring';
   346→  }
   347→
   348→  const mainPulse = matchPulseType(dimensions, metrics);
   349→  const constitution = assessConstitution(dimensions, mainPulse, metrics);
   350→  const organAnalysis = analyzeOrgans(dimensions, mainPulse, metrics);
   351→  const recommendations = generateRecommendations(dimensions, constitution, organAnalysis);
   352→
   353→  return { mainPulse, dimensions, constitution, organAnalysis, recommendations, segmentTrend, timestamp: Date.now() };
   354→}
