    29→export function median(values) {
    30→  if (!values || values.length === 0) return 0;
    31→  const s = values.slice().sort((a, b) => a - b);
    32→  const mid = Math.floor(s.length / 2);
    33→  return s.length % 2 ? s[mid] : (s[mid - 1] + s[mid]) / 2;
