   274→      jumpRatio: +jumpRatio.toFixed(3),
   275→      coverageSeconds: +coverageSeconds.toFixed(1),
   276→      rejectedCount: this.rejectedDataPoints,
   277→      score,
   278→      level
   279→    };
   280→  }
   281→
   282→  // 符号动力学熵（Pattern Entropy）：把 BPM 差分序列符号化（升 U/降 D/平 F），
   283→  // 统计长度为 3 的模式频率并计算香农熵。熵高 = 节律模式多样（灵活），
   284→  // 熵低 = 节律僵化。用于 diagnosePulse 修正 SDNN。
   285→  calculatePatternEntropy(bpmSeq) {
   286→    if (bpmSeq.length < 10) return 0;
   287→    const symbols = [];
   288→    for (let i = 1; i < bpmSeq.length; i++) {
   289→      const diff = bpmSeq[i] - bpmSeq[i-1];
   290→      if (diff > 0) symbols.push('U');
   291→      else if (diff < 0) symbols.push('D');
   292→      else symbols.push('F');
   293→    }
   294→
   295→    // 统计长度为3的模式频率
   296→    const patternCount = {};
   297→    let totalPatterns = 0;
   298→    for (let i = 0; i <= symbols.length - 3; i++) {
   299→      const pat = symbols.slice(i, i+3).join('');
   300→      patternCount[pat] = (patternCount[pat] || 0) + 1;
   301→      totalPatterns++;
   302→    }
   303→
   304→    // 计算香农熵
   305→    let entropy = 0;
   306→    for (const key in patternCount) {
   307→      const p = patternCount[key] / totalPatterns;
   308→      if (p > 0) entropy -= p * Math.log2(p);
   309→    }
   310→    return entropy;
   311→  }
   312→
   313→  // 简易带通滤波求 RMS (代替FFT) 提取 LF 和 VLF
   314→  // 简易实现：通过求移动平均的差值来模拟频段分离
   315→  // 注：这是对真实频谱分析的近似——VLF(<0.04Hz)用 ±25s 移动均值代表基线，
   316→  // LF(0.04-0.15Hz)用 ±7s 移动均值减去基线；结果供 diagnosePulse 用 LF/VLF
   317→  // 比值粗略估计交感/迷走平衡，非临床级频域指标。
   318→  calculateBandRMS(bpmSeq) {
   319→    if (bpmSeq.length < 30) return { lfRms: 0, vlfRms: 0 };
   320→
   321→    // VLF (<0.04Hz): 用极长窗口(25秒)移动平均代表极低频基线
   322→    const vlfWindow = 25;
   323→    const vlfBaseline = [];
   324→    for(let i=0; i<bpmSeq.length; i++) {
   325→      let sum = 0, count = 0;
   326→      for(let j=Math.max(0, i-vlfWindow); j<=Math.min(bpmSeq.length-1, i+vlfWindow); j++) {
   327→        sum += bpmSeq[j]; count++;
   328→      }
   329→      vlfBaseline.push(sum/count);
   330→    }
   331→
   332→    // LF (0.04-0.15Hz): 用较短窗口(7秒)移动平均减去 VLF 基线
   333→    const lfWindow = 7;
   334→    const lfSignal = [];
   335→    for(let i=0; i<bpmSeq.length; i++) {
   336→      let sum = 0, count = 0;
   337→      for(let j=Math.max(0, i-lfWindow); j<=Math.min(bpmSeq.length-1, i+lfWindow); j++) {
   338→        sum += bpmSeq[j]; count++;
   339→      }
   340→      lfSignal.push((sum/count) - vlfBaseline[i]);
   341→    }
   342→
   343→    // 计算 RMS
   344→    const lfRms = Math.sqrt(lfSignal.reduce((s, v) => s + v*v, 0) / lfSignal.length);
   345→    // VLF 波动是相对于整体均值的
   346→    const globalMean = bpmSeq.reduce((a,b)=>a+b,0)/bpmSeq.length;
   347→    const vlfRms = Math.sqrt(vlfBaseline.reduce((s, v) => s + Math.pow(v-globalMean, 2), 0) / vlfBaseline.length);
   348→
   349→    return { lfRms, vlfRms };
   350→  }
   351→
   352→  // 汇总采集结果：低于 10 个有效 RR 视为测量失败，返回 null
   353→  getHrvMetrics() {
   354→    if (this.rrIntervals.length < 10) return null;
   355→    const rr = this.rrIntervals;
   356→    const meanRR = this.calculateMeanRR(rr);
   357→    const sdnn = this.calculateSDNN(rr);
   358→    const meanHR = meanRR != null ? 60000 / meanRR : null;
   359→
   360→    // 计算符号熵
   361→    const patternEntropy = this.calculatePatternEntropy(this.bpmBuffer);
   362→
   363→    // 计算 LF/VLF RMS
   364→    const { lfRms, vlfRms } = this.calculateBandRMS(this.bpmBuffer);
   365→
   366→    return {
   367→      sdnn: sdnn != null ? +sdnn.toFixed(2) : null,
   368→      mean_rr: meanRR != null ? +meanRR.toFixed(2) : null,
   369→      mean_hr: meanHR != null ? +meanHR.toFixed(1) : null,
   370→      patternEntropy: +patternEntropy.toFixed(3),
   371→      lfRms: +lfRms.toFixed(2),
   372→      vlfRms: +vlfRms.toFixed(2)
   373→    };
   374→  }
   375→}
