   377→// -------------------------------------
   378→// 全天传感器基线数据
   379→// 从手表传感器读取全天统计，作为脉象诊断的补充维度：
   380→//   sdann      — 全天分 5 分钟段的 RR 均值标准差（衡量长期变异性）
   381→//   stressVal  — 全天压力平均值
   382→//   sleepScore — 昨晚睡眠时长打分（0-10）
   383→//   hrReserve  — 全天心率极差（最高-最低）
   384→//   restingHr  — 全天静息心率（最低值，或传感器 getResting）
   385→// 各传感器读取均有 try/catch 兜底，单一项失败不影响整体。
   386→// -------------------------------------
   387→function fetchAllDayMetrics() {
   388→  let sdann = 0, stressVal = 0, sleepScore = 0, hrReserve = 0, restingHr = 0;
   389→  try {
   390→    const hr = new HeartRate();
   391→    const hrData = hr.getToday();
   392→    if (Array.isArray(hrData) && hrData.length > 0) {
   393→      const valid = hrData.filter(v => typeof v === 'number' && isFinite(v) && v > 30 && v <= 220);
   394→      if (valid.length > 0) {
   395→        let mh = Infinity, Mh = 0;
   396→        valid.forEach(v => { if (v < mh) mh = v; if (v > Mh) Mh = v; });
   397→        hrReserve = Mh - mh; restingHr = mh;
   398→        const daily = deriveFromHrArray(hrData);
   399→        sdann = daily && daily.sdann != null ? daily.sdann : 0;
   400→      }
   401→    }
   402→    if (typeof hr.getResting === 'function') { try { const r = hr.getResting(); if (r > 0) restingHr = Math.round(r); } catch (e) {} }
   403→  } catch (e) {}
   404→  try {
   405→    const st = new Stress();
   406→    const arr = st.getTodayByHour();
   407→    if (Array.isArray(arr) && arr.length > 0) {
   408→      const vv = arr.filter(v => typeof v === 'number' && v > 0);
   409→      if (vv.length > 0) stressVal = Math.round(vv.reduce((a, b) => a + b, 0) / vv.length);
   410→    }
   411→  } catch (e) {}
   412→  try {
   413→    const sl = new Sleep();
   414→    const info = sl.getInfo();
   415→    if (info && info.totalTime > 0) {
   416→      const m = info.totalTime;
   417→      if (m >= 420 && m <= 540) sleepScore = 10; else if (m >= 360) sleepScore = 8;
   418→      else if (m >= 300) sleepScore = 6; else if (m >= 240) sleepScore = 4; else sleepScore = 2;
   419→    }
   420→  } catch (e) {}
   421→  return { sdann, stressVal, sleepScore, hrReserve, restingHr };
   422→}
   423→
   424→// TCM 分段 SDNN + 心率稳定性
   425→// 将本次采集的 RR 序列按 60 秒分段，每段算一个 SDNN → sdnnSegments（供
   426→// diagnosePulse 判断放松/疲劳趋势）；hrStability 为整段 BPM 的标准差
   427→// （心率波动幅度，供脉形维度分类）。
   428→function calcTcmMetrics(rr) {
   429→  if (!rr || rr.length < 2) return null;
   430→  const hrVals = rr.map(r => 60000 / r);
   431→  const hrMean = hrVals.reduce((a, b) => a + b, 0) / hrVals.length;
   432→  const hrStab = Math.sqrt(hrVals.reduce((s, v) => s + Math.pow(v - hrMean, 2), 0) / hrVals.length);
   433→  const segs = []; let acc = 0, srr = [];
   434→  for (let i = 0; i < rr.length; i++) {
   435→    acc += rr[i]; srr.push(rr[i]);
   436→    if (acc >= 60000 && srr.length >= 5) {
   437→      const sm = srr.reduce((a, b) => a + b, 0) / srr.length;
   438→      segs.push(+Math.sqrt(srr.reduce((s, r) => s + Math.pow(r - sm, 2), 0) / (srr.length - 1)).toFixed(2));
   439→      srr = []; acc = 0;
   440→    }
   441→  }
   442→  return { hrStability: +hrStab.toFixed(2), sdnnSegments: segs, rrCount: rr.length };
   443→}
   444→
   445→// RSA: 从 BPM 序列提取 E/I ratio (呼吸-心率耦合指数)
   446→// 呼吸使心率周期性起伏（吸气升、呼气降）。去趋势后取局部峰=吸气相心率、
   447→// 谷=呼气相心率，E/I ≈ 平均峰值 / 平均谷值。峰谷用其在原序列的真实索引取回 BPM。
   448→// 返回值 1.x：>1.15 迷走灵活，<1.03 迷走迟钝（阈值见 pulse_diagnosis.classifyRsa）。
   449→function calcRsaEiRatio(bpmSeq) {
   450→  if (!bpmSeq || bpmSeq.length < 30) return 0;
   451→
   452→  // 去趋势：减去 ±5 窗口移动均值，保留呼吸尺度的波动
   453→  const detr = [];
   454→  for (let i = 0; i < bpmSeq.length; i++) {
   455→    let sum = 0, cnt = 0;
   456→    for (let j = Math.max(0, i - 5); j <= Math.min(bpmSeq.length - 1, i + 5); j++) { sum += bpmSeq[j]; cnt++; }
   457→    detr.push(bpmSeq[i] - sum / cnt);
   458→  }
   459→
   460→  // 在去趋势信号上找局部峰/谷，用真实索引取回对应 BPM
   461→  const peaks = [], troughs = [];
   462→  for (let i = 1; i < detr.length - 1; i++) {
   463→    if (detr[i] > detr[i - 1] && detr[i] >= detr[i + 1]) peaks.push(bpmSeq[i]);
   464→    else if (detr[i] < detr[i - 1] && detr[i] <= detr[i + 1]) troughs.push(bpmSeq[i]);
   465→  }
   466→  if (peaks.length < 2 || troughs.length < 2) return 0;
   467→
   468→  const avgPeak = peaks.reduce((a, b) => a + b, 0) / peaks.length;
   469→  const avgTrough = troughs.reduce((a, b) => a + b, 0) / troughs.length;
   470→  if (avgTrough <= 0) return 0;
   471→  return +(avgPeak / avgTrough).toFixed(3);
   472→}
