   648→  // 呼吸引导动画：6 次/分钟（5s 吸 + 5s 呼，0.1Hz 共振呼吸），正弦缓动缩放圆 + 吸/呼文字
   649→  startBreathing() {
   650→    this.stopBreathing();
   651→    const { width, height } = getDeviceInfo();
   652→    const baseSize = pl(420), maxScale = 1.35, minScale = 1;   // 呼吸图近满屏，吸气时略溢出
   653→    const half = 100;                                          // 100 步 × 50ms = 5s 吸 + 5s 呼 = 6 次/分钟
   654→    let step = 0, dir = 1;
   655→    if (this.state.breathHintText) this.state.breathHintText.setProperty(prop.TEXT, getText('inhale'));
   656→    this.state.breathTimer = setInterval(() => {
   657→      step += dir;
   658→      const eased = -(Math.cos(Math.PI * (step / half)) - 1) / 2;   // easeInOutSine
   659→      const size = Math.round(baseSize * (minScale + (maxScale - minScale) * eased));
   660→      if (this.state.breathImg) {
   661→        this.state.breathImg.setProperty(prop.MORE, { x: Math.round((width - size) / 2), y: Math.round((height - size) / 2), w: size, h: size });
   662→        this.state.breathImg.setAlpha(Math.round(120 + 135 * eased));
   663→      }
   664→      if (step >= half) { dir = -1; if (this.state.breathHintText) this.state.breathHintText.setProperty(prop.TEXT, getText('exhale')); }
   665→      else if (step <= 0) { dir = 1; if (this.state.breathHintText) this.state.breathHintText.setProperty(prop.TEXT, getText('inhale')); }
   666→    }, 50);
   667→  },
