+    const diffCount = Math.max(1, raw.length - 1);
+    const freezeRatio = frozen / diffCount;
+    const jumpRatio = jumps / diffCount;
+    let coverageSeconds = 0;
+    if (this.bpmSamples.length >= 2) {
