+    const updateScore = 1 - Math.min(1, Math.max(0, freezeRatio - 0.60) / 0.40);
+    const continuityScore = 1 - Math.min(1, jumpRatio / 0.15);
+    const coverageScore = Math.min(1, coverageSeconds / Math.max(1, dur - 10));
