     1→/**
     2→ * relative_text.js — 「较你的常态」个体化文案层
     3→ *
     4→ * 双轨融合把六维数值改成了相对个人常态的判定；本层负责把同样的"相对"信息，
     5→ * 用一句文雅、不制造焦虑的话讲给用户（标签/脉名保持绝对，个体化叙事交给这里）。
     6→ *
     7→ * 能力边界（诚实原则）：基线目前只有 hr / rhythm / delta / stress 四个特征，
     8→ * 故只有 rate(脉数) / rhythm(脉律) / rsa(恢复) / tension(张力) 能说"较你常态"；
     9→ * strength(脉力)、width(脉形) 无基线 → 返回 null，页面自动不显示该行。
    10→ *
    11→ * 冷启动/无基线：sampleCount < MIN_BASELINE_SAMPLES 时一律返回 null（回落纯绝对文案）。
    12→ */
    13→
    14→import { getText } from './i18n';
    15→import { getBaseline, extractFeatures, MIN_BASELINE_SAMPLES } from './baseline_manager';
    16→
    17→function tr(key, fallback) {
    18→  const value = getText(key);
    19→  return value && value !== key ? value : fallback;
    20→}
    21→
    22→// 维度 → 基线特征 + 中文兜底（msgid = dim_relative_<key>_<dir>）
    23→const DIM_FEATURE = { rate: 'hr', rhythm: 'rhythm', rsa: 'delta', tension: 'stress' };
    24→const FALLBACK = {
    25→  rate_below: '心跳比平时慢一些',
    26→  rate_within: '心跳和平时差不多',
    27→  rate_above: '心跳比平时快一些',
    28→  rhythm_below: '心跳比平时更规律',
    29→  rhythm_within: '心跳和平时一样规律',
    30→  rhythm_above: '心跳比平时稍微有点不规律',
    31→  rsa_below: '测量时，身体比平时更快平静下来',
    32→  rsa_within: '测量时，和平时一样慢慢平静下来',
    33→  rsa_above: '测量时，比平时不太容易平静下来',
    34→  tension_below: '身体比平时放松',
    35→  tension_within: '身体和平时一样，比较放松',
    36→  tension_above: '身体比平时紧张一些',
    37→  steady: '这次的结果和你平时差不多',
    38→};
    39→
    40→const BAND = 0.8; // |z| 小于此视为"在常态范围内"
    41→
    42→// 是否有可用基线（页面据此决定是否显示"对照常态"区）
    43→export function hasBaseline() {
    44→  const b = getBaseline();
    45→  return !!(b && b.sampleCount >= MIN_BASELINE_SAMPLES);
    46→}
    47→
    48→// 计算某维相对常态的方向；不支持/无基线/数据不合格 → null
    49→export function relativeOf(key, metrics) {
    50→  const feat = DIM_FEATURE[key];
    51→  if (!feat || !metrics) return null;
    52→  const base = getBaseline();
    53→  if (!base || base.sampleCount < MIN_BASELINE_SAMPLES || !base[feat] || !(base[feat].mad > 0)) return null;
    54→  const f = extractFeatures({ metrics });
    55→  if (!f || typeof f[feat] !== 'number' || !isFinite(f[feat]) || !isFinite(base[feat].med) || !isFinite(base[feat].mad)) return null;
    56→  const z = (f[feat] - base[feat].med) / base[feat].mad;
    57→  const dir = z < -BAND ? 'below' : z > BAND ? 'above' : 'within';
    58→  return { dir, z };
    59→}
    60→
    61→// 六维深度页 / 五脏页用：某维的一句"较你常态"
    62→export function relativeLine(key, metrics) {
    63→  const r = relativeOf(key, metrics);
    64→  if (!r) return null;
    65→  return tr(`dim_relative_${key}_${r.dir}`, FALLBACK[`${key}_${r.dir}`] || '');
    66→}
    67→
    68→// 主报告 headline / 体质页用：取偏离最明显的一维说一句；全在常态内则给"稳"
    69→export function overallRelative(metrics) {
    70→  const base = getBaseline();
    71→  if (!base || base.sampleCount < MIN_BASELINE_SAMPLES) return null;
    72→  const cand = [];
    73→  let observed = 0;
    74→  ['rate', 'rhythm', 'tension', 'rsa'].forEach(k => {
    75→    const r = relativeOf(k, metrics);
    76→    if (r) observed++;
    77→    if (r && r.dir !== 'within') cand.push({ k, z: r.z, dir: r.dir });
    78→  });
    79→  if (!observed) return null;
    80→  if (cand.length === 0) return tr('relative_steady', FALLBACK.steady);
    81→  cand.sort((a, b) => Math.abs(b.z) - Math.abs(a.z));
    82→  const top = cand[0];
    83→  return tr(`dim_relative_${top.k}_${top.dir}`, FALLBACK[`${top.k}_${top.dir}`] || '');
    84→}
