+    const now = new Date();
+    const year = now.getFullYear();
+    const month = now.getMonth(); // 0-11
+    this.monthLabel = year + '年' + (month + 1) + '月';
+    const todayStr = year + '-' + pad(month + 1) + '-' + pad(now.getDate());
+
+    const storage = new HrvStorageManager();
+    storage.init(() => {
+      storage.getHistoryIndex((index) => {
+        storage.getTodayData((todayData) => {
+          const set = {};
+          (index || []).forEach((d) => { set[d] = true; });
+          if (todayData && todayData.length) set[todayStr] = true;
+
+          // 本月有记录天数
+          const monthPrefix = year + '-' + pad(month + 1) + '-';
+          let cnt = 0;
+          Object.keys(set).forEach((d) => { if (d.indexOf(monthPrefix) === 0) cnt++; });
+          this.recordCount = cnt;
+
+          const firstWeekday = new Date(year, month, 1).getDay();
+          const lastDay = new Date(year, month + 1, 0).getDate();
+          const cells = [];
+          for (let i = 0; i < firstWeekday; i++) cells.push({ label: '', color: 'transparent', bold: 'normal', dotOpacity: 0 });
+          for (let day = 1; day <= lastDay; day++) {
+            const ds = monthPrefix + pad(day);
+            const has = !!set[ds];
+            const isToday = ds === todayStr;
+            let color = '#5A4632';
+            let bold = 'normal';
+            if (has) { color = '#B77B22'; bold = 'bold'; }
+            if (isToday) { color = has ? '#B77B22' : '#3A2A18'; }
+            cells.push({ label: String(day), color: color, bold: bold, dotOpacity: has ? 1 : 0 });
+          }
+          this.cells = cells;
+        });
+      });
+    });
+  }
