```
buildChart(values, dates, color) {
  // values array of numbers (last 7), dates parallel
  const n = values.length;
  if (n<2) return { empty:true };
  let lo=Infinity,hi=-Infinity; values.forEach(v=>{lo=Math.min(lo,v);hi=Math.max(hi,v);});
  const med=median(values), madv=mad(values,med);
  lo=Math.min(lo,med-madv); hi=Math.max(hi,med+madv);
  if(hi-lo<1){hi=lo+1;}
  const span=hi-lo; lo-=span*0.08; hi+=span*0.08;
  const W=306,H=120;
  const mapY=v=>Math.round(clamp((1-(v-lo)/(hi-lo))*H,2,H-2));
  const stepX=W/(n-1);
  const pts=values.map((v,i)=>({x:Math.round(i*stepX),y:mapY(v)}));
  // dense line dots
  const line=[];
  for(let i=0;i<pts.length-1;i++){
    const a=pts[i],b=pts[i+1];
    const steps=Math.max(1,Math.round(Math.max(Math.abs(b.x-a.x),Math.abs(b.y-a.y))/10));
    for(let k=0;k<=steps;k++){const t=k/steps;line.push({x:Math.round(a.x+(b.x-a.x)*t),y:Math.round(a.y+(b.y-a.y)*t)});}
  }
  const bandTop=mapY(med+madv), bandBot=mapY(med-madv);
  return { empty:false, pts, line, bandTop, bandH:Math.max(2,bandBot-bandTop), latest:values[n-1], med, madv, color, firstDate:dates[0], lastDate:dates[n-1], unit:'次/分' };
}
```
