deriveDay(dateStr, recs): 
```
let minHr=Infinity, sumHr=0, n=0, morningHr=null, morningTs=Infinity, lastHr=null, lastTs=0;
recs.forEach(r=>{
  const m=r.metrics||{}; const hr=(m.dynamics&&m.dynamics.medianHr)||m.mean_hr||0;
  if(hr>0&&hr<minHr)minHr=hr;
  if(hr>0){sumHr+=hr;n++;}
  const ts=r.timestamp||0;
  if(ts<morningTs&&hr>0){morningTs=ts;morningHr=hr;}
  if(ts>lastTs){lastTs=ts;lastHr=hr;}
});
if(!n)return null;
return {date:dateStr, restingHr:Math.round(minHr), morningHr:morningHr?Math.round(morningHr):null, meanHr:Math.round(sumHr/n), lastHr:lastHr?Math.round(lastHr):null};
```

Chart build for a metric over daily (last 7 with value>0):
```
buildChart(daily, key, color) {
  const pts = daily.filter(d=>typeof d[key]==='number'&&d[key]>0).slice(-7);
  const n=pts.length;
  if(n<2) return {empty:true, title...};
  const values=pts.map(p=>p[key]);
  let lo=Math.min(...values), hi=Math.max(...values);
  const med=median(values), madv=mad(values,med);
  lo=Math.min(lo,med-madv); hi=Math.max(hi,med+madv);
  if(hi-lo<1)hi=lo+1;
  const span=hi-lo; lo-=span*0.08; hi+=span*0.08;
  const W=306,H=120;
  const mapY=v=>Math.round(Math.max(2,Math.min(H-2,(1-(v-lo)/(hi-lo))*H)));
  const stepX=W/(n-1);
  const dots=values.map((v,i)=>({x:Math.round(i*stepX),y:mapY(v)}));
  // dense line
  const line=[];
  for(let i=0;i<dots.length-1;i++){
    const a=dots[i],b=dots[i+1];
    const steps=Math.max(1,Math.round(Math.max(Math.abs(b.x-a.x),Math.abs(b.y-a.y))/8));
