  }
  const bandTop=mapY(med+madv), bandBot=mapY(med-madv);
  const latest=values[n-1]; const d=Math.round(latest-med);
  return {empty:false,color,W,H,dots,line,bandTop,bandH:Math.max(2,bandBot-bandTop),latest,firstDate:md(pts[0].date),lastDate:md(pts[n-1].date),
    sub: med? ('较你的常值 '+(d===0?'持平':(d>0?'高':'低')+' '+Math.abs(d))):'' , d};
}
