   139→export function calcTcmMetrics(rr) {
   140→  if (!rr || rr.length < 2) return null;
   141→  const hrVals = rr.map(r => 60000 / r);
   142→  const hrMean = hrVals.reduce((a, b) => a + b, 0) / hrVals.length;
   143→  const hrStab = Math.sqrt(hrVals.reduce((s, v) => s + Math.pow(v - hrMean, 2), 0) / hrVals.length);
