   145→  for (let i = 0; i < rr.length; i++) {
   146→    acc += rr[i]; srr.push(rr[i]);
   147→    if (acc >= 60000 && srr.length >= 5) {
   148→      const sm = srr.reduce((a, b) => a + b, 0) / srr.length;
   149→      segs.push(+Math.sqrt(srr.reduce((s, r) => s + Math.pow(r - sm, 2), 0) / (srr.length - 1)).toFixed(2));
   150→      srr = []; acc = 0;
   151→    }
   152→  }
   153→  return { hrStability: +hrStab.toFixed(2), sdnnSegments: segs, rrCount: rr.length };
   154→}
