   163→    let sum = 0, cnt = 0;
   164→    for (let j = Math.max(0, i - 5); j <= Math.min(bpmSeq.length - 1, i + 5); j++) { sum += bpmSeq[j]; cnt++; }
   165→    detr.push(bpmSeq[i] - sum / cnt);
   166→  }
   167→
   168→  const peaks = [], troughs = [];
   169→  for (let i = 1; i < detr.length - 1; i++) {
