   126→  scores.huan = (restingHr >= 55 && restingHr <= 75 ? 0.8 : 0.2) * 0.35 + (sdnn >= 35 && sdnn <= 70 ? 0.8 : 0.2) * 0.35 + (stress < 50 ? 0.6 : 0.2) * 0.3;
