   269→// ============================================================================
   270→// 趋势分析
   271→// ============================================================================
   272→export function analyzeTrend(currentSdnn, currentSdann, historyRecords) {
   273→  if (!historyRecords || historyRecords.length < 3) {
   274→    return { trend: 'insufficient_data', label: getText('trend_insufficient'), direction: 'stable', changeRate: 0 };
   275→  }
   276→  const recent = historyRecords.slice(-7);
   277→  const sdnnValues = recent.map(r => (r.metrics && r.metrics.sdnn) || r.sdnn || 0).filter(v => v > 0);
   278→  if (sdnnValues.length < 3) return { trend: 'insufficient_data', label: getText('trend_insufficient'), direction: 'stable', changeRate: 0 };
   279→
   280→  const avgSdnn = sdnnValues.reduce((a, b) => a + b, 0) / sdnnValues.length;
   281→  const changeRate = avgSdnn > 0 ? (currentSdnn - avgSdnn) / avgSdnn : 0;
   282→
   283→  let direction = 'stable', labelKey = 'trend_stable';
   284→  if (changeRate > 0.15)      { direction = 'improving'; labelKey = 'trend_improving'; }
   285→  else if (changeRate > 0.05) { direction = 'slightly_improving'; labelKey = 'trend_slightly_improving'; }
   286→  else if (changeRate < -0.15) { direction = 'declining'; labelKey = 'trend_declining'; }
   287→  else if (changeRate < -0.05) { direction = 'slightly_declining'; labelKey = 'trend_slightly_declining'; }
   288→  return { trend: direction, label: getText(labelKey), direction, changeRate: Math.round(changeRate * 100) / 100 };
   289→}
   290→
   291→// ============================================================================
   292→// RSA 呼吸-心率耦合评估
   293→// ============================================================================
   294→function classifyRsa(eiRatio) {
   295→  if (eiRatio == null || eiRatio <= 0) return { value: 0, category: 'unknown', label: getText('dim_label_unknown'), score: 5 };
   296→  if (eiRatio < 1.03) return { value: eiRatio, category: 'rigid',      label: getText('dim_label_rsa_rigid'),      score: 2 };
   297→  if (eiRatio < 1.06) return { value: eiRatio, category: 'blunted',    label: getText('dim_label_rsa_blunted'),    score: 4 };
   298→  if (eiRatio < 1.10) return { value: eiRatio, category: 'normal',     label: getText('dim_label_rsa_normal'),     score: 6 };
   299→  if (eiRatio < 1.15) return { value: eiRatio, category: 'flexible',   label: getText('dim_label_rsa_flexible'),   score: 8 };
   300→  return { value: eiRatio, category: 'highly_flexible', label: getText('dim_label_rsa_highly_flexible'), score: 9 };
   301→}
   302→
   303→// ============================================================================
   304→// 主入口
   305→// ============================================================================
   306→export function diagnosePulse(metrics) {
   307→  const { 
   308→    sdnn = 0, sdann = 0, restingHr = 0, avgHr = 0, mean_hr = 0, 
   309→    hrStability = 0, sdnnSegments = [], stress = 0, sleepScore = 0, 
   310→    hrReserve = 0, patternEntropy = 0, lfRms = 0, vlfRms = 0,
   311→    rsaEiRatio = 0
   312→  } = metrics;
   313→
   314→  // 使用新提取的非线性指标 (Pattern Entropy) 和 频域 (LF/VLF RMS) 修正节律和宽度
   315→  let adjustedSdnn = sdnn;
   316→  let adjustedStress = stress;
   317→
   318→  if (patternEntropy > 0) {
   319→    if (patternEntropy < 1.0) adjustedSdnn = Math.max(0, adjustedSdnn - 10);
   320→    else if (patternEntropy > 2.5) adjustedSdnn = Math.min(100, adjustedSdnn + 10);
   321→  }
   322→
   323→  if (lfRms > 0 && vlfRms > 0) {
   324→    const lfVlfRatio = lfRms / vlfRms;
   325→    if (lfVlfRatio > 2.0) adjustedStress = Math.min(100, adjustedStress + 15);
   326→    else if (lfVlfRatio < 0.5) adjustedStress = Math.max(0, adjustedStress - 15);
   327→  }
   328→
   329→  const dimensions = {
   330→    rate:     classifyRate(restingHr || avgHr || mean_hr),
   331→    rhythm:   classifyRhythm(adjustedSdnn),
   332→    strength: classifyStrength(sdann, hrReserve),
   333→    width:    classifyWidth(hrStability, adjustedStress),
   334→    tension:  classifyTension(adjustedStress, adjustedSdnn),
   335→    rsa:      classifyRsa(rsaEiRatio)
   336→  };
   337→
   338→  let segmentTrend = 'stable';
   339→  if (sdnnSegments.length >= 3) {
   340→    const first = sdnnSegments.slice(0, Math.ceil(sdnnSegments.length / 2));
   341→    const second = sdnnSegments.slice(Math.ceil(sdnnSegments.length / 2));
   342→    const avgFirst = first.reduce((a, b) => a + b, 0) / first.length;
   343→    const avgSecond = second.reduce((a, b) => a + b, 0) / second.length;
   344→    if (avgFirst > 0 && avgSecond / avgFirst > 1.1) segmentTrend = 'relaxing';
   345→    else if (avgFirst > 0 && avgSecond / avgFirst < 0.9) segmentTrend = 'tiring';
   346→  }
   347→
   348→  const mainPulse = matchPulseType(dimensions, metrics);
   349→  const constitution = assessConstitution(dimensions, mainPulse, metrics);
   350→  const organAnalysis = analyzeOrgans(dimensions, mainPulse, metrics);
   351→  const recommendations = generateRecommendations(dimensions, constitution, organAnalysis);
   352→
   353→  return { mainPulse, dimensions, constitution, organAnalysis, recommendations, segmentTrend, timestamp: Date.now() };
   354→}
