   315→// TCM 分段 SDNN + 心率稳定性
   316→export function calcTcmMetrics(rr) {
   317→  if (!rr || rr.length < 2) return null;
   318→  const hrVals = rr.map(r => 60000 / r);
   319→  const hrMean = hrVals.reduce((a, b) => a + b, 0) / hrVals.length;
   320→  const hrStab = Math.sqrt(hrVals.reduce((s, v) => s + Math.pow(v - hrMean, 2), 0) / hrVals.length);
   321→  const segs = []; let acc = 0, srr = [];
   322→  for (let i = 0; i < rr.length; i++) {
   323→    acc += rr[i]; srr.push(rr[i]);
   324→    if (acc >= 60000 && srr.length >= 5) {
   325→      const sm = srr.reduce((a, b) => a + b, 0) / srr.length;
   326→      segs.push(+Math.sqrt(srr.reduce((s, r) => s + Math.pow(r - sm, 2), 0) / (srr.length - 1)).toFixed(2));
   327→      srr = []; acc = 0;
   328→    }
   329→  }
   330→  return { hrStability: +hrStab.toFixed(2), sdnnSegments: segs, rrCount: rr.length };
   331→}
