   333→// RSA: 从 BPM 序列提取 E/I ratio（呼吸-心率耦合指数）
   334→export function calcRsaEiRatio(bpmSeq) {
   335→  if (!bpmSeq || bpmSeq.length < 30) return 0;
   336→
   337→  // 去趋势：减去 ±5 窗口移动均值，保留呼吸尺度的波动
   338→  const detr = [];
   339→  for (let i = 0; i < bpmSeq.length; i++) {
   340→    let sum = 0, cnt = 0;
   341→    for (let j = Math.max(0, i - 5); j <= Math.min(bpmSeq.length - 1, i + 5); j++) { sum += bpmSeq[j]; cnt++; }
   342→    detr.push(bpmSeq[i] - sum / cnt);
   343→  }
   344→
   345→  const peaks = [], troughs = [];
   346→  for (let i = 1; i < detr.length - 1; i++) {
   347→    if (detr[i] > detr[i - 1] && detr[i] >= detr[i + 1]) peaks.push(bpmSeq[i]);
   348→    else if (detr[i] < detr[i - 1] && detr[i] <= detr[i + 1]) troughs.push(bpmSeq[i]);
   349→  }
   350→  if (peaks.length < 2 || troughs.length < 2) return 0;
   351→
   352→  const avgPeak = peaks.reduce((a, b) => a + b, 0) / peaks.length;
   353→  const avgTrough = troughs.reduce((a, b) => a + b, 0) / troughs.length;
   354→  if (avgTrough <= 0) return 0;
   355→  return +(avgPeak / avgTrough).toFixed(3);
   356→}
