   171→  const stressPart = stress > 0 ? 1 - clamp(stress / 100, 0, 1) : 0.5;
   172→  const sleepPart = sleepScore > 0 ? clamp(sleepScore / 10, 0, 1) : 0.5;
   173→  let recovery = deltaPart * 0.40 + stabilityPart * 0.30 + stressPart * 0.15 + sleepPart * 0.15;
   174→  if (firstLastDelta == null && legacyEiRatio > 0) recovery = clamp((legacyEiRatio - 1.0) / 0.15, 0, 1);
   175→  let category, label;
   176→  if (recovery < 0.28) { category = 'slow'; label = getText('dim_label_rsa_slow'); }
   177→  else if (recovery < 0.46) { category = 'settling'; label = getText('dim_label_rsa_settling'); }
   178→  else if (recovery < 0.68) { category = 'balanced'; label = getText('dim_label_rsa_balanced'); }
   179→  else if (recovery < 0.84) { category = 'relaxed'; label = getText('dim_label_rsa_relaxed'); }
   180→  else { category = 'improving'; label = getText('dim_label_rsa_improving'); }
   181→  const stateIdx = fuseStateIndex(recovery * 100, firstLastDelta, baseline && baseline.delta, w, true);
   182→  return dimResult(recovery, stateIdx, category, label, centeredScore(stateIdx, 68, 68), quality,
   183→    ['first_last_delta', 'late_stability', 'stress'], stress > 0 ? [] : ['stress']);
   184→}
