   186→// ============================================================================
   187→// 五脏 & 体质 (msgid)
   188→// ============================================================================
   189→// 由内部 key（organKey/statusKey）映射到五脏描述 msgid，与语言无关
   190→function organDescKey(organKey, statusKey) {
   191→  const map = {
   192→    heart:  { he: 'organ_desc_heart_he',  ping: 'organ_desc_heart_ping',  xu: 'organ_desc_heart_xu',  kui: 'organ_desc_heart_kui' },
   193→    liver:  { he: 'organ_desc_liver_he',  ping: 'organ_desc_liver_ping',  xu: 'organ_desc_liver_xu',  kui: 'organ_desc_liver_kui' },
   194→    spleen: { he: 'organ_desc_spleen_he', ping: 'organ_desc_spleen_ping', xu: 'organ_desc_spleen_xu', kui: 'organ_desc_spleen_kui' },
   195→    lung:   { he: 'organ_desc_lung_he',   ping: 'organ_desc_lung_ping',   xu: 'organ_desc_lung_xu',   kui: 'organ_desc_lung_kui' },
   196→    kidney: { he: 'organ_desc_kidney_he', ping: 'organ_desc_kidney_ping', xu: 'organ_desc_kidney_xu', kui: 'organ_desc_kidney_kui' },
   197→  };
   198→  return (map[organKey] && map[organKey][statusKey]) || '';
   199→}
