   201→// ============================================================================
   202→// 主脉象匹配 v2：使用绝对匹配度，不再把第一名强制归一化为 1。
   203→// 1Hz 心率能够稳定支持的特征优先，浮/沉/结/代保留在知识库中。
   204→// ============================================================================
   205→function matchPulseType(dimensions, metrics) {
   206→  const hr = metrics.medianHr || metrics.mean_hr || metrics.restingHr || 0;
   207→  const stress = metrics.stress || 0;
   208→  const range = metrics.hrRange90 || 0;
   209→  const hrMad = metrics.hrMad || 0;
   210→  const successiveMad = metrics.successiveMad || 0;
   211→  const jumpRatio = metrics.jumpRatio || 0;
   212→  const quality = metrics.qualityScore == null ? 0.7 : metrics.qualityScore / 100;
   213→  const smooth = 1 - clamp(jumpRatio / 0.15, 0, 1);
   214→  const strengthIndex = (dimensions.strength.stateIndex == null ? 50 : dimensions.strength.stateIndex) / 100;
   215→  const widthIndex = (dimensions.width.stateIndex == null ? 50 : dimensions.width.stateIndex) / 100;
   216→  const tensionIndex = (dimensions.tension.stateIndex == null ? 50 : dimensions.tension.stateIndex) / 100;
   217→  const rhythmBalance = dimensions.rhythm.score / 9;
   218→  const scores = {};
   219→
   220→  scores.chi = clamp((58 - hr) / 18, 0, 1) * 0.80 + (hr < 58 ? 0.12 : 0.02);
   221→  scores.shuo = clamp((hr - 76) / 24, 0, 1) * 0.80 + (hr > 76 ? 0.12 : 0.02);
   222→  scores.huan = clamp(1 - Math.abs(hr - 68) / 26, 0, 1) * 0.38 + rhythmBalance * 0.34 +
   223→    (1 - Math.abs(tensionIndex - 0.48)) * 0.18 + smooth * 0.10;
   224→  scores.xian = tensionIndex * 0.55 + clamp((stress - 35) / 65, 0, 1) * 0.25 +
   225→    clamp((hr - 65) / 30, 0, 1) * 0.20;
   226→  scores.hua = smooth * 0.35 + clamp(range / 12, 0, 1) * 0.25 +
   227→    clamp((metrics.patternEntropy || 0) / 3, 0, 1) * 0.20 + rhythmBalance * 0.20;
   228→  scores.se = (1 - smooth) * 0.42 + clamp(successiveMad / 5, 0, 1) * 0.28 +
   229→    tensionIndex * 0.20 + (1 - quality) * 0.10;
   230→  scores.xu = (1 - strengthIndex) * 0.62 + (1 - dimensions.rate.score / 9) * 0.18 +
   231→    (1 - quality) * 0.20;
   232→  scores.shi = strengthIndex * 0.62 + dimensions.rate.score / 9 * 0.18 + quality * 0.20;
   233→  scores.xi = (1 - widthIndex) * 0.62 + (1 - strengthIndex) * 0.23 + smooth * 0.15;
   234→
   235→  // 洪脉保留为较常见的充盛型倾向，但不再由全天极值单独触发。
   236→  scores.hong = clamp(range / 14, 0, 1) * 0.35 + strengthIndex * 0.30 + smooth * 0.20 +
   237→    clamp((metrics.dayRange || 0) / 45, 0, 1) * 0.15;
   238→  if (range < 5 || strengthIndex < 0.45) scores.hong *= 0.72;
   239→
   240→  // 低质量数据不产生极端文化映射，优先回落到缓脉或混合特征。
   241→  if (quality < 0.65) {
   242→    ['hua', 'se', 'xu', 'shi', 'xi', 'hong'].forEach(function (k) { scores[k] *= 0.72; });
   243→    scores.huan *= 0.90;
   244→  }
   245→
   246→  // 排序保留计算精度，避免一位小数把不同匹配度变成同分。
   247→  Object.keys(scores).forEach(function (k) { scores[k] = clamp(scores[k], 0, 1); });
   248→  const ranked = rankKeys(scores);
   249→  const bestType = ranked[0] || 'huan';
   250→  const bestScore = scores[bestType] || 0;
   251→  const secondType = ranked[1] || null;
   252→  const secondScore = secondType ? scores[secondType] : 0;
   253→  const margin = Math.max(0, bestScore - secondScore);
   254→  const confidence = clamp(bestScore * 0.55 + clamp(margin / 0.25, 0, 1) * 0.25 + quality * 0.20, 0, 1);
   255→  const certainty = confidence >= 0.75 ? 'primary' : confidence >= 0.60 ? 'close' : confidence >= 0.45 ? 'mixed' : 'unclear';
   256→
   257→  const PULSE_TYPES = resolvePulseTypes();
   258→  const info = PULSE_TYPES[bestType];
   259→  const secondInfo = secondType ? PULSE_TYPES[secondType] : null;
   260→  return {
   261→    type: bestType, name: info.name, description: info.desc, nature: info.nature,
   262→    confidence: round1(confidence), certainty: certainty,
   263→    secondary: secondInfo ? { type: secondType, name: secondInfo.name, score: secondScore } : null,
   264→    margin: round1(margin), allScores: scores
   265→  };
   266→}
