   268→// ============================================================================
   269→// 体质判定（中医九种体质）
   270→// ============================================================================
   271→function assessConstitution(dimensions, mainPulse, metrics, baseline, w) {
   272→  const stress = metrics.stress || 0;
   273→  const hr = metrics.medianHr || metrics.restingHr || 0;
   274→  const scores = {};
   275→  const strengthLow = clamp((45 - dimensions.strength.stateIndex) / 45, 0, 1);
   276→  const tensionHigh = clamp((dimensions.tension.stateIndex - 48) / 52, 0, 1);
   277→  const widthHigh = clamp((dimensions.width.stateIndex - 55) / 45, 0, 1);
   278→  const rhythmVariable = clamp(dimensions.rhythm.stateIndex / 100, 0, 1);
   279→  const balanceAvg = (dimensions.rate.score + dimensions.rhythm.score + dimensions.strength.score + dimensions.width.score + dimensions.tension.score + dimensions.rsa.score) / 54;
   280→
   281→  // 相对个人常态的心率 z：无基线/冷启动时 null → 下面三个绝对阈值项与旧版完全一致。
   282→  const zHr = (w && baseline && baseline.hr && finite(baseline.hr.med) && finite(baseline.hr.mad) && baseline.hr.mad > 0)
   283→    ? (hr - baseline.hr.med) / baseline.hr.mad : null;
   284→  // 绝对阈值虽触发，但若"只是他自己的常态"，按基线成熟度 w 向 floor 回拉、弱化病理性判定（保留绝对锚）。
   285→  function softenAbs(term, full, floor, support) {
   286→    if (zHr == null || term <= floor) return term;
   287→    return full - (full - floor) * clamp(w * clamp(1 - support, 0, 1), 0, 1);
   288→  }
   289→  const slowSupport = zHr == null ? 0 : clamp(-zHr, 0, 1);
   290→  const fastSupport = zHr == null ? 0 : clamp(zHr, 0, 1);
   291→
   292→  scores.balanced = clamp(balanceAvg, 0, 1) * 0.85;
   293→  scores.qi_deficiency = strengthLow * 0.60 + (1 - dimensions.rsa.score / 9) * 0.40;
   294→  scores.yang_deficiency = softenAbs(hr > 0 && hr < 58 ? 0.65 : 0.18, 0.65, 0.18, slowSupport) * 0.45 + strengthLow * 0.55;
   295→  scores.yin_deficiency = softenAbs(hr > 78 ? 0.65 : 0.18, 0.65, 0.18, fastSupport) * 0.45 + clamp(stress / 100, 0, 1) * 0.55;
   296→  scores.qi_stagnation = clamp(stress / 85, 0, 1) * 0.55 + tensionHigh * 0.45;
   297→  scores.blood_stasis = rhythmVariable * 0.35 + tensionHigh * 0.35 + (mainPulse.type === 'se' ? 0.30 : 0.08);
   298→  scores.phlegm_damp = strengthLow * 0.45 + widthHigh * 0.35 + (metrics.sleepScore > 0 && metrics.sleepScore < 6 ? 0.20 : 0.06);
   299→  scores.damp_heat = softenAbs(hr > 74 ? 0.45 : 0.15, 0.45, 0.15, fastSupport) * 0.35 + clamp(stress / 90, 0, 1) * 0.40 + clamp((dimensions.strength.stateIndex - 55) / 45, 0, 1) * 0.25;
   300→  scores.allergic = 0.12 + rhythmVariable * 0.18;
   301→
   302→  const ranked = rankKeys(scores);
   303→  const bestType = ranked[0] || 'balanced';
   304→  const bestScore = scores[bestType] || 0;
   305→  const secondType = ranked[1] || null;
   306→  const secondScore = secondType ? scores[secondType] : 0;
   307→  const CONSTITUTIONS = resolveConstitutions();
   308→  const cnst = CONSTITUTIONS[bestType];
   309→  return {
   310→    type: bestType, name: cnst.name, description: cnst.desc,
   311→    score: round1(clamp(bestScore, 0, 1)), margin: round1(Math.max(0, bestScore - secondScore)),
   312→    confidence: round1(clamp((metrics.qualityScore == null ? 72 : metrics.qualityScore) / 100 * 0.5 + Math.max(0, bestScore - secondScore) * 2 * 0.5, 0, 1)),
   313→    allScores: scores
   314→  };
   315→}
