   317→// ============================================================================
   318→// 五脏关联
   319→// ============================================================================
   320→function analyzeOrgans(dimensions, mainPulse, metrics) {
   321→  const stress = metrics.stress || 0;
   322→  const sleepScore = metrics.sleepScore || 0;
   323→  const quality = clamp((metrics.qualityScore == null ? 72 : metrics.qualityScore) / 100, 0, 1);
   324→  const heartScore = dimensions.rhythm.score * 0.45 + dimensions.rate.score * 0.30 + (sleepScore || 6) * 0.15 + quality * 10 * 0.10;
   325→  const liverScore = dimensions.tension.score * 0.55 + (stress > 0 ? (100 - stress) / 10 : 6) * 0.30 + dimensions.rsa.score * 0.15;
   326→  const spleenScore = dimensions.width.score * 0.35 + dimensions.strength.score * 0.45 + (sleepScore || 6) * 0.20;
   327→  const lungScore = dimensions.strength.score * 0.40 + dimensions.rhythm.score * 0.40 + dimensions.rsa.score * 0.20;
   328→  const kidneyScore = dimensions.strength.score * 0.50 + dimensions.rsa.score * 0.30 + (sleepScore || 6) * 0.20;
   329→
   330→  const organs = [
   331→    { organ: getText('organ_name_heart'), organKey: 'heart', score: round1(clamp(heartScore, 0, 10)) },
   332→    { organ: getText('organ_name_liver'), organKey: 'liver', score: round1(clamp(liverScore, 0, 10)) },
   333→    { organ: getText('organ_name_spleen'), organKey: 'spleen', score: round1(clamp(spleenScore, 0, 10)) },
   334→    { organ: getText('organ_name_lung'), organKey: 'lung', score: round1(clamp(lungScore, 0, 10)) },
   335→    { organ: getText('organ_name_kidney'), organKey: 'kidney', score: round1(clamp(kidneyScore, 0, 10)) },
   336→  ];
   337→
   338→  organs.forEach(function (o) {
   339→    if (o.score >= 7) { o.statusKey = 'he'; o.status = getText('organ_status_he'); }
   340→    else if (o.score >= 5) { o.statusKey = 'ping'; o.status = getText('organ_status_ping'); }
   341→    else if (o.score >= 3) { o.statusKey = 'xu'; o.status = getText('organ_status_xu'); }
   342→    else { o.statusKey = 'kui'; o.status = getText('organ_status_kui'); }
   343→    o.desc = getText(organDescKey(o.organKey, o.statusKey));
   344→    o.confidence = round1(quality);
   345→  });
   346→  return organs;
   347→}
