   349→// ============================================================================
   350→// 养生建议
   351→// 根据体质类型、最虚弱脏器、六维细分级三维联动生成个性化建议。
   352→// ============================================================================
   353→function generateRecommendations(dimensions, constitution, organAnalysis, metrics) {
   354→  const recs = [];
   355→  const separator = getText('rec_separator');
   356→  const isFast = dimensions.rate.category === 'pian_shuo' || dimensions.rate.category === 'shuo';
   357→  const isTense = dimensions.tension.category === 'pian_xian' || dimensions.tension.category === 'xian';
   358→  const isWeak = dimensions.strength.category === 'xu' || dimensions.strength.category === 'pian_xu';
   359→  const isFull = dimensions.width.category === 'pian_hong' || dimensions.width.category === 'hong';
   360→  const slowRecovery = dimensions.rsa.category === 'slow' || dimensions.rsa.category === 'settling';
   361→  const ct = constitution.type;
   362→
   363→  // ── 饮食：体质专属 → 六维补充 ──
   364→  const diet = [];
   365→  const dietByConstitution = {
   366→    qi_deficiency:   'rec_diet_qi_def',
   367→    yang_deficiency: 'rec_diet_yang_def',
   368→    yin_deficiency:  'rec_diet_yin_def',
   369→    qi_stagnation:   'rec_diet_qi_stag',
   370→    phlegm_damp:     'rec_diet_phlegm_damp',
   371→    damp_heat:       'rec_diet_damp_heat',
   372→    blood_stasis:    'rec_diet_blood_stasis',
   373→    allergic:        'rec_diet_allergic',
   374→  };
   375→  const dietKey = dietByConstitution[ct];
   376→  if (dietKey) {
   377→    diet.push(getText(dietKey));
   378→  } else {
   379→    diet.push(getText('rec_diet_default'));
   380→  }
   381→  if (isFast && isTense) diet.push(getText('rec_diet_calm'));
   382→  recs.push({ category: getText('rec_cat_diet'), advice: diet.join(separator), priority: isFast || isTense ? 1 : 3 });
   383→
   384→  // ── 作息：最虚弱脏器 → 张力/恢复补充 ──
   385→  const rest = [];
   386→  const sortedOrgans = organAnalysis.slice().sort((a, b) => a.score - b.score);
   387→  const worstOrgan = sortedOrgans[0];
   388→  if (worstOrgan && worstOrgan.organKey === 'liver' && worstOrgan.score < 5) {
   389→    rest.push(getText('rec_rest_liver'));
   390→  } else if (worstOrgan && worstOrgan.organKey === 'heart' && worstOrgan.score < 5) {
   391→    rest.push(getText('rec_rest_heart'));
   392→  } else if (isWeak || slowRecovery) {
   393→    rest.push(getText('rec_rest_recovery'));
   394→  } else if (isTense || isFast) {
   395→    rest.push(getText('rec_rest_calm'));
   396→  } else {
   397→    rest.push(getText('rec_rest_default'));
   398→  }
   399→  if (isTense || isFast) rest.push(getText('rec_rest_no_caffeine'));
   400→  recs.push({ category: getText('rec_cat_rest'), advice: rest.join(separator), priority: isWeak || slowRecovery ? 1 : 2 });
   401→
   402→  // ── 运动：力量维/宽度维/恢复维细分级 ──
   403→  const exercise = [];
   404→  if (isWeak || slowRecovery) {
   405→    exercise.push(getText('rec_exercise_gentle'));
   406→  } else if (isFull) {
   407→    exercise.push(getText('rec_exercise_cardio'));
   408→  } else if (isTense) {
   409→    exercise.push(getText('rec_exercise_relax'));
   410→  } else {
   411→    exercise.push(getText('rec_exercise_default'));
   412→  }
   413→  recs.push({ category: getText('rec_cat_exercise'), advice: exercise.join(separator), priority: 2 });
   414→
   415→  // ── 情志：体质类型 + 张力维联动 ──
   416→  const mind = [];
   417→  if (ct === 'qi_stagnation') {
   418→    mind.push(getText('rec_mind_social'));
   419→    if (isTense) mind.push(getText('rec_mind_no_anger'));
   420→  } else if (isTense) {
   421→    mind.push(getText('rec_mind_meditate'));
   422→    mind.push(getText('rec_mind_no_anger'));
   423→  } else if (slowRecovery) {
   424→    mind.push(getText('rec_mind_unwind'));
   425→  } else {
   426→    mind.push(getText('rec_mind_default'));
   427→  }
   428→  recs.push({ category: getText('rec_cat_mind'), advice: mind.join(separator), priority: isTense ? 1 : 3 });
   429→
   430→  return recs;
   431→}
