   433→// ============================================================================
   434→// 趋势分析（保留 Vela 现有实现，供其它页面引用）
   435→// ============================================================================
   436→export function analyzeTrend(currentSdnn, currentSdann, historyRecords) {
   437→  if (!historyRecords || historyRecords.length < 3) {
   438→    return { trend: 'insufficient_data', label: getText('trend_insufficient'), direction: 'stable', changeRate: 0 };
   439→  }
   440→  const recent = historyRecords.slice(-7);
   441→  const sdnnValues = recent.map(r => (r.metrics && r.metrics.sdnn) || r.sdnn || 0).filter(v => v > 0);
   442→  if (sdnnValues.length < 3) return { trend: 'insufficient_data', label: getText('trend_insufficient'), direction: 'stable', changeRate: 0 };
   443→
   444→  const avgSdnn = sdnnValues.reduce((a, b) => a + b, 0) / sdnnValues.length;
   445→  const changeRate = avgSdnn > 0 ? (currentSdnn - avgSdnn) / avgSdnn : 0;
   446→
   447→  let direction = 'stable', labelKey = 'trend_stable';
   448→  if (changeRate > 0.15)      { direction = 'improving'; labelKey = 'trend_improving'; }
   449→  else if (changeRate > 0.05) { direction = 'slightly_improving'; labelKey = 'trend_slightly_improving'; }
   450→  else if (changeRate < -0.15) { direction = 'declining'; labelKey = 'trend_declining'; }
   451→  else if (changeRate < -0.05) { direction = 'slightly_declining'; labelKey = 'trend_slightly_declining'; }
   452→  return { trend: direction, label: getText(labelKey), direction, changeRate: Math.round(changeRate * 100) / 100 };
   453→}
