   455→// ============================================================================
   456→// 主入口：兼容旧版指标，并优先使用 v2 心率动态与质量字段。
   457→// ============================================================================
   458→export function diagnosePulse(metrics, baseline) {
   459→  metrics = metrics || {};
   460→  const dynamics = metrics.dynamics || {};
   461→  const signalQuality = metrics.signalQuality || {};
   462→  const medianHr = [dynamics.medianHr, metrics.mean_hr, metrics.avgHr, metrics.restingHr].filter(validHr)[0];
   463→  // 没有有效心率时交给页面已有的空态；不把缺失值解释成迟脉/平和。
   464→  if (medianHr == null) return null;
   465→  // 未显式传入基线时回退到会话缓存（由 baseline_manager.refreshBaseline 预热）。
   466→  // 无基线 → w=0 → 六维行为与旧版完全一致（冷启动/未刷新安全）。
   467→  if (baseline === undefined) baseline = getBaseline();
   468→  const _sampleCount = bounded(baseline && baseline.sampleCount, 0, 10000, 0);
   469→  const _fusionW = Math.min(0.6, _sampleCount / 14 * 0.6);
   470→  // Vela 无全天心率/压力/睡眠数据源，长时程基线恒缺 → wLT=0 → strength 与旧版一致。
   471→  const _ltIndex = null, _wLT = 0;
   472→  const longterm = null;
   473→
   474→  const legacyStability = bounded(metrics.hrStability, 0, 220, null);
   475→  const hrMad = bounded(dynamics.hrMad, 0, 220, legacyStability == null ? null : legacyStability * 0.67);
   476→  const successiveMad = bounded(dynamics.successiveMad, 0, 220, hrMad == null ? null : hrMad * 0.55);
   477→  const hrRange90 = bounded(dynamics.hrRange90, 0, 220, legacyStability == null ? null : Math.min(18, legacyStability * 2.6));
   478→  const trendSlope = bounded(dynamics.trendSlope, -220, 220, 0);
   479→  const firstLastDelta = bounded(dynamics.firstLastDelta, -220, 220, null);
   480→  const patternEntropy = bounded(dynamics.patternEntropy, 0, Math.log2(27), bounded(metrics.patternEntropy, 0, Math.log2(27), null));
   481→  const jumpRatio = bounded(signalQuality.jumpRatio, 0, 1, 0);
   482→  const qualityScore = bounded(signalQuality.score, 0, 100, 72);
   483→  const quality = clamp(qualityScore / 100, 0.2, 1);
   484→  const dayRange = bounded(metrics.dayRange, 0, 45, bounded(metrics.hrReserve, 0, 45, 0));
   485→  const stress = bounded(metrics.stress, 0, 100, 0);
   486→  const sleepScore = bounded(metrics.sleepScore, 0, 10, 0);
   487→  const restingHr = validHr(metrics.restingHr) ? metrics.restingHr : 0;
   488→
   489→  const derivedMetrics = Object.assign({}, metrics, {
   490→    medianHr: medianHr, hrMad: hrMad, successiveMad: successiveMad, hrRange90: hrRange90, trendSlope: trendSlope,
   491→    firstLastDelta: firstLastDelta, patternEntropy: patternEntropy, jumpRatio: jumpRatio, qualityScore: qualityScore,
   492→    dayRange: dayRange, stress: stress, sleepScore: sleepScore, restingHr: restingHr,
   493→  });
   494→
   495→  const dimensions = {
   496→    rate: classifyRate(medianHr, quality, baseline, _fusionW),
   497→    rhythm: classifyRhythm(hrMad, successiveMad, jumpRatio, quality, baseline, _fusionW),
   498→    strength: classifyStrength(dayRange, sleepScore, stress, firstLastDelta || 0, quality, _ltIndex, _wLT),
   499→    width: classifyWidth(hrRange90, hrMad, patternEntropy, quality),
   500→    tension: classifyTension(stress, medianHr, restingHr, successiveMad, trendSlope, sleepScore, quality, baseline, _fusionW),
